/*

    Triangulated Spiral Pattern
    ---------------------------

    (Original header comments remain.)

*/

// Shifting upper and lower halves to create the spiral pattern.
#define SPIRAL

// Use highlighting.
#define HIGHLIGHT

// Add the colorful blinking lights.
#define BLINK

// Rounded spiral, as opposed to straight edge sections.
#define ROUND


// Standard 2D rotation formula.
mat2 r2(in float a){ float c = cos(a), s = sin(a); return mat2(c, s, -s, c); }

// IQ's vec2 to float hash formula.
float hash21(vec2 p){ return fract(sin(dot(p, vec2(27.617, 57.643)))*43758.5453); }

// IQ's signed distance to a 2D triangle.
float sdTri(in vec2 p, in vec2 p0, in vec2 p1, in vec2 p2){
    vec2 e0 = p1 - p0, e1 = p2 - p1, e2 = p0 - p2;
    vec2 v0 = p - p0, v1 = p - p1, v2 = p - p2;
    vec2 pq0 = v0 - e0*clamp( dot(v0, e0)/dot(e0, e0), 0., 1.);
    vec2 pq1 = v1 - e1*clamp( dot(v1, e1)/dot(e1, e1), 0., 1.);
    vec2 pq2 = v2 - e2*clamp( dot(v2, e2)/dot(e2, e2), 0., 1.);

    float s = sign( e0.x*e2.y - e0.y*e2.x);
    vec2 d = min( min( vec2(dot(pq0, pq0), s*(v0.x*e0.y - v0.y*e0.x)),
                       vec2(dot(pq1, pq1), s*(v1.x*e1.y - v1.y*e1.x))),
                       vec2(dot(pq2, pq2), s*(v2.x*e2.y - v2.y*e2.x)));

    return -sqrt(d.x)*sign(d.y);
}

////////
// A 2D triangle partitioning routine.

vec2 skewXY(vec2 p, vec2 s){ return mat2(1, -s.yx, 1)*p; }
vec2 unskewXY(vec2 p, vec2 s){ return inverse(mat2(1, -s.yx, 1))*p; }

vec2 scale = vec2(1./18., 1./6.);

float gTri;

vec4 getTriVerts(in vec2 p, inout vec2[3] vID, inout vec2[3] v){
    vec2 rect = (vec2(length(vec2(1./3., 1)), 1))*scale;
    vec2 sk = vec2(rect.x*.5, 0)/scale.y;
    p = skewXY(p, sk);

    vec2 id = floor(p/rect) + .5; 
    p -= id*rect; 

    gTri = dot(p, 1./rect) < 0. ? 1. : -1.;
    p = unskewXY(p, sk);

    if(gTri < 0.){
        vID = vec2[3](vec2(-1.5, 1.5), vec2(1.5, -1.5), vec2(1.5));
    }
    else {
        vID = vec2[3](vec2(1.5, -1.5), vec2(-1.5, 1.5), vec2(-1.5));
    }

    for(int i = 0; i < 3; i++) 
        v[i] = unskewXY(vID[i]*rect/3., sk);

    vec2 ctr = v[2]/3.;
    p -= ctr;
    v[0] -= ctr; v[1] -= ctr; v[2] -= ctr;

    vec2 ctrID = (vID[0] + vID[1] + vID[2])/3.;
    id = id*3. + ctrID;
    vID[0] -= ctrID; vID[1] -= ctrID; vID[2] -= ctrID;

    return vec4(p, id);
}

// IQ's signed distance to a 2D box.
float sBoxS(in vec2 p, in vec2 b, in float sf){
  vec2 d = abs(p) - b + sf;
  return min(max(d.x, d.y), 0.) + length(max(d, 0.)) - sf;
}


void mainImage(out vec4 fragColor, in vec2 fragCoord){

    // Aspect-correct screen coordinates.
    float iRes = iResolution.y;
    vec2 uv = (fragCoord.xy - iResolution.xy*.5) / iRes;

    float sf = 1. / iRes; 
    vec2 p = r2(iTime/16.) * uv;

    vec2 ld = normalize(vec2(-1, -1));

    const float rNum = 6.;
    #ifdef SPIRAL
      float yDir = p.y < 0. ? -1. : 1.;
      p.x -= yDir * length(vec2(1./3., 2)) / (rNum * 4.);
    #endif

    float a = atan(p.y, p.x);
    const float CELL_NUM = 18.;
    float na = floor(a / 6.2831853 * CELL_NUM);
    float ia = (na + .5) / CELL_NUM;

    p *= r2(ia*6.2831853);
    ld *= r2(ia*6.2831853);

    #ifdef ROUND
      p.x = length(p);
    #endif

    float iR = floor(p.x / scale.y); 

    vec2[3] vID, v;
    vec4 p4 = getTriVerts(p.yx, vID, v);
    p = p4.xy;

    float tri = sdTri(p, v[0], v[1], v[2]);
    float triHi = sdTri(p - ld.yx*.001, v[0], v[1], v[2]);
    float b = max(triHi - tri, 0.) / .001;
    float b2 = max(tri - triHi, 0.) / .001;

    float dir = mod(na, 2.) < .5 ? -1. : 1.;  

    // ────── COLOR SETUP (Pastel pink and pastel yellow with blink highlights) ──────
    vec3 tCol = (gTri*dir > 0.) 
                  ? vec3(1.0, 0.7, 0.9)  // Pastel pink
                  : vec3(1.0, 1.0, 0.6); // Pastel yellow

    #ifdef BLINK
      float rnd = hash21(p4.zw + na + dir*iR*128.);
      float blink = smoothstep(.96, .985, sin(6.2831*rnd + mod(iTime, 6.2831))*.5 + .5);
      if(gTri*dir > 0.)
        tCol = mix(tCol, vec3(1.0, 0.6, 0.5), blink); // Blend to an orange tone.
      else
        tCol = mix(tCol, vec3(1.0, 1.0, 0.8), blink); // A subtler blend.

      tCol = mix(tCol, tCol.xzy, max(-uv.y, 0.));
    #endif
    // ────────────────────────────────────────────────────────────────────────────────

    #ifdef HIGHLIGHT
      vec3 lCol = vec3(.3, .6, 1)*b*b + vec3(1, .6, .2)*b2*b2;
    #else 
      vec3 lCol = vec3(.66);
      if(gTri*dir < 0.) lCol *= .4;
    #endif

    tCol = tCol * (.65 + lCol*.5);

    // A gentle adjustment for alternating triangles.
    if(gTri*dir < 0.)
       tCol = mix(tCol, tCol*0.8, 0.5);

    // ────── MODIFYING THE EDGE / BACKGROUND COLOR ──────
    // Originally, the triangles were drawn over a nearly-black background (vec3(.05)).
    // Here we change that to a pale green. (Replace with vec3(1.0) for white.)
    vec3 lineColor = vec3(0.8, 1.0, 0.9);
    vec3 col = mix(lineColor, tCol, 1. - smoothstep(0., sf, tri + .02*scale.y));

    #ifdef HIGHLIGHT
      float shF = iResolution.y / 450.;
      col = mix(col, vec3(0), (1. - smoothstep(0., sf*shF*4., abs(tri)))*.35);
    #endif

    vec2 d = abs(uv) - vec2(iResolution.x/iResolution.y, 1)/2.;
    float bord = min(max(d.x, d.y), 0.) + length(max(d, 0.)) - sf;
    col = mix(col, vec3(.3, .6, 1)/8., (1. - smoothstep(0., .05, abs(bord)))*.5);

    fragColor = vec4(sqrt(max(col, 0.)), 1);
}
